  // the dolphin for the Body Manual: pixel art with shading (dark back, light belly), dorsal fin, flukes, one eye open
  function drawDolphin(c, x, y, t) { const P = (xx, yy, w, h, col) => { c.fillStyle = col; c.fillRect(x + xx, y + yy, w, h); };
    for (let yy = -9; yy <= 9; yy++) for (let xx = -36; xx <= 36; xx++) { const d = (xx * xx) / (36 * 36) + (yy * yy) / (9 * 9); if (d <= 1) P(xx, yy, 1, 1, yy < -3 ? '#2a4a7a' : yy < 3 ? '#4a6aa8' : '#c8d8e8'); }
    for (let k = 0; k < 10; k++) P(-4 + k, -9 - Math.floor((10 - k) * 1.1), 10 - k, 1, '#2a4a7a');                                   // dorsal fin
    for (let k = 0; k < 8; k++) { P(-44 + k, -10 + k, 4, 1, '#2a4a7a'); P(-44 + k, 9 - k, 4, 1, '#4a6aa8'); }                      // tail flukes
    for (let k = 0; k < 5; k++) P(28 + k, -6 + k, 3, 1, '#2a4a7a'); P(34, 0, 6, 3, '#4a6aa8'); P(34, 3, 5, 1, '#c8d8e8'); for (let k = 0; k < 6; k++) P(6 + k, 6 + k, 3, 1, '#2a4a7a');        // snout, flipper
    P(22, -4, 5, 4, '#ffffff'); P(24 - (Math.floor(t * 2) % 2), -3, 2, 2, '#101018'); P(22, -5, 5, 1, '#1a2a4a'); }
